mapper.select:
select count(distinct a.subject_id) as count, a.label_id as labelId, c.label_name as labelName from subject_mapping a, subject_info b, subject_label c where a.subject_id = b.id and a.label_id = c.id and a.is_deleted = 0 and b.is_deleted = 0 and c.is_deleted = 0 and a.category_id = #{categoryId} and b.subject_type in
#{item}
group by a.label_id, c.label_name
